package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadClaim {
    public void load(@PathVariable("sheetId") String sheetId, @PathVariable("claimId") long claimId,
            Claims claims, Out<Claim> claimOut) throws ClaimNotFoundException {
        Claim claim = claims.find(sheetId, claimId);
        if (claim == null) throw new ClaimNotFoundException(claimId);
        claimOut.set(claim);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithClaim {
    public void respond(@Val Claim claim, Figures figures, ClaimLog log, ObjectResponse<ClaimResponse> response) {
        response.send(ClaimResponse.from(claim, figures, log.of(claim)));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;

public class SaveClaim {
    public void save(@Val Claim claim, Claims claims) {
        claims.save(claim);
    }
}
